const articles = $input.first().json.articles;

const lignes = articles.map((a, i) => {
  const titre = (a.title || '')
    .replace(/[^\x20-\x7E]/g, '')
    .replace(/["\\]/g, '')
    .replace(/:/g, '-')
    //.substring(0, 70)
    .trim();
  const lien = (a.link || '').trim();
  const content = (a.output || '').trim();
  return (i + 1) + '. ' + titre + ' >>> ' + lien  + ' >>> ' + content;
});

const texte = lignes.join(' ||| ');

return [{ json: { texte, count: articles.length } }];

// Recursive Text Splitter for Notion page blocks
const CHUNK_SIZE = 1900;
const SEPARATORS = ['\n\n', '\n', '. ', ' '];

const inputText = $input.first().json.output || '';

function splitText(text, separators, chunkSize) {
  if (text.length <= chunkSize) return [text];
  const results = [];
  let remaining = text;
  while (remaining.length > chunkSize) {
    let splitAt = -1;
    for (const sep of separators) {
      const idx = remaining.lastIndexOf(sep, chunkSize);
      if (idx > 0) { splitAt = idx + sep.length; break; }
    }
    if (splitAt <= 0) splitAt = chunkSize;
    results.push(remaining.slice(0, splitAt));
    remaining = remaining.slice(splitAt);
  }
  if (remaining.length > 0) results.push(remaining);
  return results;
}

const chunks = splitText(inputText, SEPARATORS, CHUNK_SIZE);
return chunks.map((chunk, index) => ({
  json: {
    chunkIndex: index + 1,
    totalChunks: chunks.length,
    text: chunk.trim(),
    firstBlock: index === 0
  }
}));

